-- GenDB engine variant Q21-commuted_comparisons: template q21.sql, kind commuted_comparisons (generated by generate.py; frozen)
SELECT
  s_name,
  COUNT(*) AS numwait
FROM supplier, lineitem AS l1, orders, nation
WHERE
  l1.l_suppkey = s_suppkey
  AND l1.l_orderkey = o_orderkey
  AND 'F' = o_orderstatus
  AND l1.l_commitdate < l1.l_receiptdate
  AND EXISTS(
    SELECT
      *
    FROM lineitem AS l2
    WHERE
      l1.l_orderkey = l2.l_orderkey AND l1.l_suppkey <> l2.l_suppkey
  )
  AND NOT EXISTS(
    SELECT
      *
    FROM lineitem AS l3
    WHERE
      l1.l_orderkey = l3.l_orderkey
      AND l1.l_suppkey <> l3.l_suppkey
      AND l3.l_commitdate < l3.l_receiptdate
  )
  AND n_nationkey = s_nationkey
  AND $1 = n_name
GROUP BY
  s_name
ORDER BY
  numwait DESC,
  s_name
LIMIT 100
